def solve(s: str) -> str:
    if not s:
        return ""

    parts = []
    current = s[0]
    count = 1

    for char in s[1:]:
        if char == current:
            count += 1
        else:
            parts.append(current + str(count))
            current = char
            count = 1

    parts.append(current + str(count))
    return "".join(parts)

def solve(s: str) -> bool:
    depth = 0
    for char in s:
        if char == '(':
            depth += 1
        elif char == ')':
            depth -= 1
            if depth < 0:
                return False
        else:
            return False
    return depth == 0

def solve(s: str) -> int:
    values = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}
    total = 0
    for i, symbol in enumerate(s):
        value = values[symbol]
        if i + 1 < len(s) and value < values[s[i + 1]]:
            total -= value
        else:
            total += value
    return total

def solve(nums: list) -> int:
    n = len(nums)
    return n * (n + 1) // 2 - sum(nums)

def solve(x: list) -> int:
    total = 0
    stack = [x]
    while stack:
        item = stack.pop()
        if isinstance(item, list):
            stack.extend(item)
        else:
            total += item
    return total

def solve(a: int, b: int) -> int:
    while b:
        a, b = b, a % b
    return a

def solve(s: str) -> bool:
    normalized = ''.join(char.casefold() for char in s if char.isalnum())
    return normalized == normalized[::-1]

def solve(tokens: list) -> int:
    stack = []
    for token in tokens:
        if token in ("+", "-", "*"):
            right = stack.pop()
            left = stack.pop()
            if token == "+":
                stack.append(left + right)
            elif token == "-":
                stack.append(left - right)
            else:
                stack.append(left * right)
        else:
            stack.append(int(token))
    return stack[0]

import re

def solve(s: str) -> str:
    return re.sub(r"\S+", lambda match: match.group().capitalize(), s)

def solve(n: int) -> int:
    while n >= 10:
        total = 0
        while n:
            total += n % 10
            n //= 10
        n = total
    return n

def solve(s: str) -> str:
    result = []
    for char in s:
        if not result or result[-1] != char:
            result.append(char)
    return "".join(result)
